import{_ as s,l as n,o as a,c as l,v as t,p as i,x as r,d as c,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Borg 与 Kubernetes","description":"","frontmatter":{"title":"Borg 与 Kubernetes","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/borg-kubernetes.md","filePath":"cs/borg-kubernetes.md","lastUpdated":1789023840000}'),p={name:"cs/borg-kubernetes.md"};function b(h,e,B,E,g,A){const o=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="borg-与-kubernetes" tabindex="-1">Borg 与 Kubernetes <a class="header-anchor" href="#borg-与-kubernetes" aria-label="Permalink to &quot;Borg 与 Kubernetes&quot;">​</a></h1><div class="epigraph"><p>集群操作系统：调度把任务放到机器上，控制面是强一致的小状态，数据面是最终一致的调和。声明式对象不等于一次 RPC 的线性化点。</p><footer>—— 据 Verma et al., Large-scale cluster management at Google with Borg, EuroSys 2015；Burns et al., Borg, Omega, and Kubernetes, CACM 2016 整理</footer></div><p>上一课<a href="/cs/distributed-fs-metadata">分布式文件元数据</a>给了卷的一种来源。缺口是<strong>谁把进程放到哪台机器</strong>：调度、隔离、控制器。本课钉 Borg 与 Kubernetes 的控制面形状，不重写 Linux cgroup。后课 Tail at Scale 解释为何调度与多租户制造长尾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Borg：作业、任务、配额、抢占、机器失败就在别处重启。单元（cell）里有 Borgmaster 复制状态。Kubernetes：API 对象存 etcd（<a href="/cs/etcd-chubby">etcd/Chubby</a>），控制器 watch 后调和到期望态——调和循环是<a href="/cs/eventual-consistency">最终一致</a>，etcd 里对象写是线性一致。缺口：把 <code>kubectl apply</code> 当全集群瞬间完成。调度器看到的是缓存的快照，决策可过时，靠再调和。</p><p>Omega 的共享状态调度、乐观并发是亲戚，Burns 文对照三代。</p><p><span class="marginnote">EuroSys 2015 讲 Borg 生产。CACM 2016 讲设计迁移。本课不把 YAML 当理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制面：少数主，CP。kubelet/代理：本机，失败隔离。调度：过滤 + 打分；绑定写回 etcd 带资源版本（乐观锁）。抢占与优先级处理过载，不是限流课的令牌桶，但同族。</p>',9)),(a(),i(u,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20API%5B%22API%20%2F%20etcd%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20SCH%20--%3E%20BIND%5B%22%E7%BB%91%E5%AE%9A%E8%8A%82%E7%82%B9%22%5D%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20REC%5B%22%E8%B0%83%E5%92%8C%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20REC%20--%3E%20API%0A%20%20KUBE%5B%22kubelet%22%5D%20--%3E%20RUN%5B%22%E8%B7%91%E5%AE%B9%E5%99%A8%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>不要把滚动升级（后课）当成调度算法本身；它是控制器对副本集的调和。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>故障：机器没心跳，任务被重新调度，本地盘要当临时。与<a href="/cs/leases">租约</a>：节点心跳是检测器。脑裂：两个调度器若不用资源版本会双绑——etcd 条件写是 fencing。</p><p>本课不写服务网格。也不写 LLM 训练作业调度。</p><p>多租户尾延迟：邻居 noisy，cgroup 不完美，这是 Tail at Scale 的输入。隔离档（best effort vs guaranteed）是 Borg 已有分类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部 API 对象。后课默认：编排 = 强一致存储 + 最终一致调和；读到「已 Running」不表示所有副本同时切完。下一课把规模下的尾从机房层再钉一次。地理复制课处理多集群，不在本课。</p><p>声明式把重试变成调和。调和不是 2PC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Borg/k8s：控制面 CP，控制器最终一致调和。</li><li>调度绑定用对象版本防双绑。</li><li>机器失败靠检测与在别处重启，本地状态要可丢。</li><li>出处：Verma et al., EuroSys 2015；Burns et al., CACM 2016。</li></ul>',10))])}const f=s(p,[["render",b]]);export{_ as __pageData,f as default};
